#!/bin/bash
# spiral.config.sh — Pelangi Capsule Hostel Website
# Generated by Spiral skill 2026-03-13

# No validation command (Next.js build is slow; TypeScript check is used instead)
SPIRAL_VALIDATE_CMD="cd site && npx tsc --noEmit 2>&1"

# Story prefix
SPIRAL_STORY_PREFIX="US"

# Disable optional features that require external CLIs
SPIRAL_RESEARCH_SPECIALIST_PROMPT=""
SPIRAL_GEMINI_PROMPT=""
SPIRAL_GEMINI_ANNOTATE_PROMPT=""
SPIRAL_FIRECRAWL_ENABLED=0
SPIRAL_GITNEXUS_REPO=""

# Auto-archive passed stories when prd.json exceeds this many total stories
SPIRAL_AUTO_ARCHIVE_THRESHOLD=300

# Blog posts have large HTML content — raise diff limit (default 500 is too low for content stories)
SPIRAL_MAX_DIFF_LINES=2000

# Memory watchdog disabled (Windows compatibility)
SPIRAL_MEMORY_WATCHDOG=0

# Story cost limits
SPIRAL_STORY_COST_HARD_USD=10.00
SPIRAL_STORY_COST_WARN_USD=5.00

# Workers: 1 (sequential to avoid merge conflicts in Next.js files)
# Override at launch with --ralph-workers if needed
